def run(binpath, prog, stdin=b''):
    with tempfile.TemporaryDirectory() as td:
        p = subprocess.run([binpath, '-c', prog], cwd=td, input=stdin,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
    return p.returncode, p.stdout, p.stderr

def check(prog, stdin=b'', engine='l'):
    b = L if engine=='l' else CORE
    name = 'lypning-l' if engine=='l' else 'lypning'
    rc1,o1,e1 = run(b, prog, stdin)
    rc2,o2,e2 = run(PY3, prog, stdin)
    verdict = []
    if rc1 == 90:
        # contract checks
        if o1 != b'':
            verdict.append('CONTRACT: stdout before exit 90')
        lines = e1.decode('utf-8','replace').rstrip('\n').split('\n')
        if len(lines) != 1:
            verdict.append('CONTRACT: stderr line count %d' % len(lines))
        elif not lines[0].startswith(name + ': unsupported: '):
            verdict.append('CONTRACT: malformed refusal line')
        else:
            rest = lines[0][len(name+': unsupported: '):]
            if ': ' not in rest:
                verdict.append('CONTRACT: no KIND: DETAIL')
    else:
        if rc1 != rc2:
            verdict.append('EXIT: %d vs cpython %d' % (rc1, rc2))
        if o1 != o2:
            verdict.append('STDOUT DIFF')
        if rc1 == 0 and rc2 == 0 and o1 == o2:
            pass
    if b'panic' in e1 or rc1 in (101,134,139):
        verdict.append('PANIC/ABORT rc=%d' % rc1)
    return verdict, (rc1,o1,e1), (rc2,o2,e2)

def report(progs, stdin=b'', engine='l'):
    bad = 0
    for prog in progs:
        v,a,b2 = check(prog, stdin, engine)
        tag = 'OK ' if not v else 'HOLE'
        if v: bad += 1
        print('%s | %r' % (tag, prog))
        print('     lyp: rc=%d out=%r err=%r' % (a[0], a[1][:300], a[2][:300]))
        print('     cpy: rc=%d out=%r err=%r' % (b2[0], b2[1][:300], b2[2][:300]))
        if v: print('     >>> ' + '; '.join(v))
    print('---- %d checked, %d flagged' % (len(progs), bad))

