import ast
def feat(s):
    try: t=ast.parse(s)
    except SyntaxError: return ("<syntax>",)
    imps=set(); names=collections.Counter()
    for n in ast.walk(t):
        if isinstance(n, ast.Import):
            for a in n.names: imps.add(a.name.split(".")[0])
        elif isinstance(n, ast.ImportFrom):
            if n.module: imps.add(n.module.split(".")[0])
        elif isinstance(n, ast.Attribute): names[n.attr]+=1
        elif isinstance(n, ast.Name): names[n.id]+=1
        else: names[type(n).__name__]+=1
    return (tuple(sorted(imps)), tuple(sorted(names)))

