    # mark nodes inside any FunctionDef
    def collect(node, inside):
        for c in ast.iter_child_nodes(node):
            ins = inside or isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef))
            if isinstance(c,ast.Attribute): (indef if ins else top).add(c.attr)
            if isinstance(c,ast.Name): (indef if ins else top).add(c.id)
            if isinstance(c,(ast.Import,ast.ImportFrom)):
