import json, ast, collections, hashlib, sys

rows = [json.loads(l) for l in open('scores.jsonl')]
W = [r for r in rows if r['grade'] == 'WASTED']
I = [r for r in rows if r['grade'] == 'IDEAL' and r['predicted'] == 'lypning']

def feats(src, level):
    try:
        t = ast.parse(src)
    except SyntaxError:
        return None
    imports, names, attrs, calls, lits = set(), set(), set(), set(), set()
    for n in ast.walk(t):
        if isinstance(n, ast.Import):
            for a in n.names: imports.add(a.name.split('.')[0])
        elif isinstance(n, ast.ImportFrom):
            if n.module: imports.add(n.module.split('.')[0])
        elif isinstance(n, ast.Attribute): attrs.add(n.attr)
        elif isinstance(n, ast.Name): names.add(n.id)
        elif isinstance(n, ast.Call) and isinstance(n.func, ast.Name): calls.add(n.func.id)
        elif isinstance(n, ast.Set): lits.add('setlit')
        elif isinstance(n, ast.Dict): lits.add('dictlit')
        elif isinstance(n, ast.Constant):
            if isinstance(n.value, int) and not isinstance(n.value, bool):
                if abs(n.value) > 2**53: lits.add('bigintlit')
            elif isinstance(n.value, float): lits.add('floatlit')
        elif isinstance(n, ast.BinOp) and isinstance(n.op, ast.Div): lits.add('truediv')
    B = {'set','frozenset','dict','sorted','round','repr','hash','id','divmod','pow','sum','open','type','float','int','listdir'}
    if level == 'coarse':
        key = tuple(sorted(imports)), tuple(sorted(calls & B)), tuple(sorted(lits))
    elif level == 'medium':
        key = (tuple(sorted(imports)), tuple(sorted(calls & B)), tuple(sorted(lits)),
               tuple(sorted(a for a in attrs if a in {'keys','items','values','difference','union','listdir','seed','random','choice'})))
    else:  # exact-ish: full normalized structure
        key = ast.dump(t, annotate_fields=False)
    return hashlib.blake2b(repr(key).encode(), digest_size=8).hexdigest()

for level in ('coarse','medium','exact-shape'):
    wk = collections.Counter()
    for r in W:
        k = feats(r['src'], level)
        if k: wk[k] += 1
    hits = sum(1 for r in I if feats(r['src'], level) in wk)
    dw = sum(1 for r in W if feats(r['src'], level) in wk)
    print('%-12s  distinct WASTED keys %3d / %d   |  IDEAL programs colliding: %4d / %d (%.1f%%)'
          % (level, len(wk), len(W), hits, len(I), 100.0*hits/len(I)))

