old = '''#[cfg(not(feature = "cap-collections"))]
pub const MODULES: &[&str] = &["sys", "os", "os.path", "io", "json", "posixpath", "random"];
#[cfg(feature = "cap-collections")]
pub const MODULES: &[&str] =
    &["sys", "os", "os.path", "io", "json", "posixpath", "random", "collections"];'''
new = '''macro_rules! modules {
    ($($cap:literal),*) => {
        pub const MODULES: &[&str] =
            &["sys", "os", "os.path", "io", "json", "posixpath", "random" $(, $cap)*];
    };
}
#[cfg(not(any(feature = "cap-collections", feature = "cap-csv")))]
modules!();
#[cfg(all(feature = "cap-collections", not(feature = "cap-csv")))]
modules!("collections");
#[cfg(all(feature = "cap-csv", not(feature = "cap-collections")))]
modules!("csv");
#[cfg(all(feature = "cap-collections", feature = "cap-csv"))]
modules!("collections", "csv");'''
assert old in s
s = s.replace(old, new)

# the doc comment above MODULES: extend the note about spelling it twice
s = s.replace(
'''/// Spelled twice rather than appended to, so the smaller variant's table is the
/// same bytes it always was: a capability that added an entry at runtime would
/// still have compiled the branch that adds it. `route::CAPS` carries the same
/// claim for the ROUTER, which has to answer for a sibling it is not.''',
'''/// One const per capability COMBINATION rather than a table appended to at
/// runtime, so the smaller variant's table is the same bytes it always was: a
/// capability that added an entry at runtime would still have compiled the
/// branch that adds it. The macro spells the core set once; the four `cfg`
/// arms below are the two capability features crossed. `route::CAPS` carries
/// the same claim for the ROUTER, which has to answer for a sibling it is not.''')

# module attributes
s = s.replace(
'''        #[cfg(feature = "cap-collections")]
        ("collections", "defaultdict") => Value::Builtin("defaultdict"),''',
'''        #[cfg(feature = "cap-collections")]
        ("collections", "defaultdict") => Value::Builtin("defaultdict"),
        // The four names 23 corpus programs import `csv` for. Every other name
        // under `csv` refuses through the arm below, and that is the whole of
        // how `csv.Error`, `csv.Sniffer`, `csv.field_size_limit`,
        // `csv.register_dialect` and 3.12's `csv.QUOTE_STRINGS` /
        // `csv.QUOTE_NOTNULL` are kept out: a program that names one never
        // reaches a line of `csv.rs`.
        #[cfg(feature = "cap-csv")]
        ("csv", "reader" | "writer" | "DictReader" | "DictWriter") => {
            Value::Bound(Rc::new(m.clone()), csv_name(name)?)
        }
        // The four quoting constants are their INTEGER values, as in CPython —
        // `csv.QUOTE_NONNUMERIC` names something real and passing it to a
        // writer is what refuses, by value, in `csv::dialect`.
        #[cfg(feature = "cap-csv")]
        ("csv", "QUOTE_MINIMAL") => Value::Int(0),
        #[cfg(feature = "cap-csv")]
        ("csv", "QUOTE_ALL") => Value::Int(1),
        #[cfg(feature = "cap-csv")]
        ("csv", "QUOTE_NONNUMERIC") => Value::Int(2),
        #[cfg(feature = "cap-csv")]
        ("csv", "QUOTE_NONE") => Value::Int(3),''')

# interned names for csv: a separate table so the core's is untouched
s = s.replace(
'''/// Method names are stored as `&'static str` in `Value::Bound`; this maps a
/// borrowed name onto the static one, refusing anything not in the table.''',
'''/// The same job as [`interned`] for the four `csv` constructors, in a table of
/// its own so that the core variant's table is the same bytes it always was.
#[cfg(feature = "cap-csv")]
fn csv_name(name: &str) -> R<&'static str> {
    const NAMES: &[&str] = &["reader", "writer", "DictReader", "DictWriter"];
    NAMES
        .iter()
        .find(|n| **n == name)
        .copied()
        .ok_or_else(|| unsupported("module-attr", name))
}

/// Method names are stored as `&'static str` in `Value::Bound`; this maps a
/// borrowed name onto the static one, refusing anything not in the table.''')

# dispatch
s = s.replace(
'''        ("random", _) => return crate::random::call(it, name, args, &kw),''',
'''        ("random", _) => return crate::random::call(it, name, args, &kw),
        #[cfg(feature = "cap-csv")]
        ("csv", _) => return crate::csv::call(it, name, args, &kw),''')
p.write_text(s)
print("ok")
